import{describe,it,expect}from"vitest";import Service from"../../frontend/js-modules/weather-service.js";describe("weather-service: buildForecastUrl",()=>{it("includes lat/lng and the daily params Open-Meteo expects",()=>{const e=Service.buildForecastUrl(26.9124,75.7873);expect(e).toContain("latitude=26.9124"),expect(e).toContain("longitude=75.7873"),expect(e).toContain("daily="),expect(e).toContain("weathercode"),expect(e).toContain(`forecast_days=${Service.FORECAST_DAYS}`)})}),describe("weather-service: buildHourlyForecastUrl",()=>{it("includes lat/lng and the hourly params Open-Meteo expects",()=>{const e=Service.buildHourlyForecastUrl(26.9124,75.7873);expect(e).toContain("latitude=26.9124"),expect(e).toContain("longitude=75.7873"),expect(e).toContain("hourly="),expect(e).toContain("precipitation_probability"),expect(e).toContain(`forecast_days=${Service.HOURLY_FORECAST_DAYS}`)}),it("requests a shorter horizon for hourly than daily forecasts",()=>{expect(Service.HOURLY_FORECAST_DAYS).toBeLessThan(Service.FORECAST_DAYS)})}),describe("weather-service: normalizeResponse",()=>{it("maps Open-Meteo daily arrays into one object per date",()=>{const e=Service.normalizeResponse({daily:{time:["2026-08-01","2026-08-02"],weathercode:[0,65],temperature_2m_max:[32,27],temperature_2m_min:[22,21],precipitation_probability_max:[5,90]}});expect(e).toHaveLength(2),expect(e[0]).toEqual({date:"2026-08-01",weatherCode:0,tempMaxC:32,tempMinC:22,precipProbability:5}),expect(e[1].weatherCode).toBe(65)}),it("returns an empty array for a missing/malformed response",()=>{expect(Service.normalizeResponse({})).toEqual([]),expect(Service.normalizeResponse(null)).toEqual([]),expect(Service.normalizeResponse({daily:{}})).toEqual([])})}),describe("weather-service: normalizeHourlyResponse",()=>{it("groups flat hourly arrays by date, preserving time-of-day",()=>{const e=Service.normalizeHourlyResponse({hourly:{time:["2026-08-01T00:00","2026-08-01T01:00","2026-08-02T00:00"],weathercode:[0,65,3],temperature_2m:[24,23,25],precipitation_probability:[5,88,10]}});expect(e).toHaveLength(2);const t=e.find(e=>"2026-08-01"===e.date);expect(t.hours).toHaveLength(2),expect(t.hours[0]).toEqual({time:"00:00",weatherCode:0,tempC:24,precipProbability:5}),expect(t.hours[1].time).toBe("01:00"),expect(t.hours[1].weatherCode).toBe(65);const o=e.find(e=>"2026-08-02"===e.date);expect(o.hours).toHaveLength(1)}),it("returns an empty array for a missing/malformed response",()=>{expect(Service.normalizeHourlyResponse({})).toEqual([]),expect(Service.normalizeHourlyResponse(null)).toEqual([]),expect(Service.normalizeHourlyResponse({hourly:{}})).toEqual([])})});